j:jelly.script:
alreadyChangedWidth = "false";
addLoadEvent(showAvailability);
addLoadEvent(showTypes);
addLoadEvent(resizeAvailability);

function showAvailability() {
  if ("${jvar_availability_check_display}" == "none") {
    toggleCheck(gel("availability_check"));
    var avail = $(document.body).select(".avail_report");
    for (var i = 0; i != avail.length; i++)
      avail[i].style.display = "none";
  }
}

function showType(t, display) {
  var set = $(document.body).select("." + t);
  if (set.length > 0) {
    if (display == "none")
      toggleCheck(gel(t + "_check"));
    else {
      for (var i = 0; set.length > i; i++)
        set[i].parentNode.parentNode.style.display = "";
    }
    gel(t).style.display = "";
  }
}

function showTypes() {
  showType("degraded", "${jvar_degraded_check_display}");
  showType("available", "${jvar_available_check_display}");
  showType("unavailable", "${jvar_unavailable_check_display}");
  showType("planned", "${jvar_planned_check_display}");
}

function toggleCheck(e) {
  if (e.getAttribute("gsft_checked") == "true") {
     e.setAttribute("gsft_checked", "false");
     e.style.backgroundImage = "";
     e.setAttribute("gsft_bgcolor", e.style.backgroundColor);
     e.style.backgroundColor = "";
  } else {
     e.setAttribute("gsft_checked", "true");
     e.style.backgroundImage = 'url("images/checked12.png")';
     e.style.backgroundColor = e.getAttribute("gsft_bgcolor");
  }
}

function toggleSet(e, type) {
  toggleCheck(e);
  var set = $(document.body).select("." + type);
  for (var i = 0; i != set.length; i++) {
    var node = set[i];
    node = node.parentNode.parentNode;
    if (e.getAttribute("gsft_checked") == "true") {
      node.style.display = "";
      deletePreference("subscription." + type + ".display");
    } else {
      node.style.display = "none";
      setPreference("subscription." + type + ".display", "none");
    }
  }
  resizeAvailability();
}

function toggleAvailability(e) {
  toggleCheck(e);
  var avail = $(document.body).select(".avail_report");
  for (var i = 0; i != avail.length; i++) {
    if (e.getAttribute("gsft_checked") == "false") {
      avail[i].style.display = "none";
      setPreference("subscription.availability.display", "none");
    } else {
      avail[i].style.display = "";
      deletePreference("subscription.availability.display");
    }
  }
  resizeAvailability();
}

function resizeAvailability() {
  var el = $(document.body).select(".sub_avail_card");
  if (alreadyChangedWidth == "false") { // only need to set widths once
    var w = 0;
    for (var i = 0; i != el.length; i++) {
      var curwItem = el[i].getElementsByTagName("table")[0]
      if (!curwItem)
        continue;

      var curw = curwItem.offsetWidth; // check width of table since only IE sets div width to match
      if (curw > w)
        w = curw;
    }
    if (w > 0) {
      w += 2;
      for (var i = 0; i != el.length; i++)
        el[i].style.width = w;
      alreadyChangedWidth = "true";
    }
  }

  var h = 0;
  for (var i = 0; i != el.length; i++) {
    el[i].style.height = "";
    if (el[i].offsetHeight > h)
      h = el[i].offsetHeight;
  }
  if (!isMSIE) // only IE gets this "right", Firefox and Chrome are 2px extra
    h = Math.max(0, h - 2);

  for (var i = 0; i != el.length; i++)
    el[i].style.height = h + 'px';
}
